const crypto = require('crypto');
const action = (params.action || 'hash').toLowerCase();
const input = params.input;
if (input === undefined || input === null) throw new Error('params.input required');
const data = typeof input === 'string' ? input : JSON.stringify(input);
if (action === 'hash') {
  const algo = (params.algo || 'sha256').toLowerCase();
  if (!['md5','sha1','sha256','sha512'].includes(algo)) throw new Error('algo must be md5/sha1/sha256/sha512');
  return { algo, input_bytes: Buffer.byteLength(data, 'utf8'), digest: crypto.createHash(algo).update(data).digest('hex') };
}
const sub = (params.subAction || params.mode || 'encode').toLowerCase();
if (action === 'base64') {
  if (sub === 'encode') return { encoded: Buffer.from(data, 'utf8').toString('base64') };
  return { decoded: Buffer.from(data, 'base64').toString('utf8') };
}
if (action === 'hex') {
  if (sub === 'encode') return { encoded: Buffer.from(data, 'utf8').toString('hex') };
  return { decoded: Buffer.from(data, 'hex').toString('utf8') };
}
if (action === 'url') {
  if (sub === 'encode') return { encoded: encodeURIComponent(data) };
  return { decoded: decodeURIComponent(data) };
}
throw new Error('Unknown action: ' + action);
